targets.expr:
label_join(
  sum by (http_request_method, http_route) (
    increase(http_server_request_duration_seconds_count{job="personal/kochwiki", deployment_environment_name="$environment", deployment_environment_name!="", http_route=~`${route:regex}`, http_route!="", http_request_method!=""}[$__range])
  ) > 0,
  "endpoint", " ", "http_request_method", "http_route"
)

label_join(
  (
    sum by (http_request_method, http_route, http_response_status_code) (
      increase(http_server_request_duration_seconds_count{job="personal/kochwiki", deployment_environment_name="$environment", deployment_environment_name!="", http_route=~`${route:regex}`, http_route!="", http_request_method!="", http_response_status_code=~"4[0-9]{2}"}[$__range])
    ) > 0
  ) * on (http_request_method, http_route, http_response_status_code) group_left (status_detail) (
    label_join(
      count_values by (http_request_method, http_route, http_response_status_code) (
        "status_count", round(
          sum by (http_request_method, http_route, http_response_status_code) (
            increase(http_server_request_duration_seconds_count{job="personal/kochwiki", deployment_environment_name="$environment", deployment_environment_name!="", http_route=~`${route:regex}`, http_route!="", http_request_method!="", http_response_status_code=~"4[0-9]{2}"}[$__range])
          ) > 0, 0.01
        )
      ),
      "status_detail", ": ", "http_response_status_code", "status_count"
    )
  ) or on (http_request_method, http_route) label_replace(
    0 * (
      sum by (http_request_method, http_route) (
        increase(http_server_request_duration_seconds_count{job="personal/kochwiki", deployment_environment_name="$environment", deployment_environment_name!="", http_route=~`${route:regex}`, http_route!="", http_request_method!=""}[$__range])
      ) > 0
    ),
    "status_detail", "No 4xx responses", "http_route", ".+"
  ),
  "endpoint", " ", "http_request_method", "http_route"
)

